(function(){"use strict";const lecture={"id":"ec214-l3","label":"Lecture 3 • Economic Growth","description":"Growth measurement, productivity drivers, theories and policy.","cumulativeId":"ec214-l3-full-v1","cumulativeLabel":"Full Lecture • Lecture 3","parts":[{"id":"ec214-l3-concept-v1","label":"Part 1 • Growth Concept, Per Person & Rule of 70","description":"Definition, measurement, standard of living and doubling time.","cards":[{"id":"growth-def","front":"Define economic growth.","back":"A sustained expansion of the PPF, measured as an increase in real GDP."},{"id":"growth-rate","front":"State the real GDP growth-rate formula.","back":"(RGDPₜ − RGDPₜ₋₁) ÷ RGDPₜ₋₁ × 100."},{"id":"rgdp-person","front":"Why use real GDP per person?","back":"It focuses on output/living-standard outcomes per individual rather than total economy size."},{"id":"per-person-condition","front":"When does real GDP per person grow?","back":"When real GDP grows faster than population."},{"id":"approx-per-person","front":"Approximate growth of real GDP per person.","back":"Real GDP growth − population growth."},{"id":"middle-income","front":"What is the lecture’s middle-income-trap implication for Thailand?","back":"Moving to a higher income group requires persistent growth in real GDP per person."},{"id":"rule70","front":"State the Rule of 70.","back":"Years to double ≈ 70 ÷ annual percentage growth rate."},{"id":"rule70-use","front":"What does the Rule of 70 connect?","back":"A growth rate to the approximate time needed for income/output to double."},{"id":"gdp-pop-trap","front":"Why can total GDP growth fail to improve average living standards?","back":"Population may grow nearly as fast as real GDP."}]},{"id":"ec214-l3-drivers-v1","label":"Part 2 • Aggregate Hours & Labor Productivity","description":"The two growth channels and the drivers of productivity.","cards":[{"id":"rgdp-identity","front":"State the lecture’s real-GDP identity.","back":"Real GDP = Aggregate Hours × Labor Productivity."},{"id":"two-channels","front":"What are the two direct channels of real GDP growth?","back":"More aggregate hours and higher labor productivity."},{"id":"hours","front":"How can average hours worked raise aggregate hours?","back":"More hours per worker increase total labor input."},{"id":"labor-force","front":"How can labor-force growth raise aggregate hours?","back":"More workers increase total labor input."},{"id":"lf-growth","front":"What determines labor-force growth in the lecture?","back":"Labor-force participation and population."},{"id":"limits","front":"Why cannot participation and hours rise forever?","back":"They face practical upper limits."},{"id":"population-source","front":"What is the lecture’s sustainable source of continued labor-quantity growth?","back":"Population growth."},{"id":"population-trap","front":"Why is population growth alone insufficient for higher real GDP per person?","back":"Output per person also requires productivity to rise enough."},{"id":"productivity-formula","front":"State the labor-productivity formula.","back":"Labor Productivity = Real GDP ÷ Aggregate Hours."},{"id":"physical-capital","front":"How does physical capital per worker affect productivity?","back":"More/better tools, machines, buildings, and capital raise output per hour."},{"id":"human-capital","front":"How does human capital affect productivity?","back":"Education, training, and job experience raise output per worker."},{"id":"technology-driver","front":"How does new technology affect productivity?","back":"Discoveries and better production methods raise output per hour."},{"id":"tech-capital","front":"Why may physical capital need to rise for technology to help?","back":"New technology often requires complementary equipment/capital to be used effectively."}]},{"id":"ec214-l3-theories-v1","label":"Part 3 • Classical, Neoclassical & New Growth Theory","description":"Three competing explanations of sustained growth and technological progress.","cards":[{"id":"classical-condition","front":"What key condition drives Classical Growth Theory?","back":"Exploding population plus limited resources creates long-run pressure on real GDP per person."},{"id":"classical-start","front":"What can initially raise real GDP per person in Classical theory?","back":"Technology advances and capital accumulation."},{"id":"classical-pop","front":"What happens after prosperity rises in Classical theory?","back":"Population growth accelerates."},{"id":"classical-cap-worker","front":"How does population growth reverse gains in Classical theory?","back":"Capital/resources per worker fall, reducing productivity and real GDP per person."},{"id":"classical-limit","front":"What limitation does the professor note for Classical theory today?","back":"Advanced-economy population behavior does not match the predicted population explosion."},{"id":"neo-core","front":"What sustains real GDP per person in Neoclassical Growth Theory?","back":"Continued technological advance."},{"id":"neo-growth","front":"What rough growth relation is used in Neoclassical theory?","back":"Real GDP growth ≈ population growth + labor-productivity growth."},{"id":"neo-invest","front":"How do saving and investment fit the Neoclassical story?","back":"They raise capital per hour so firms can exploit advancing technology."},{"id":"neo-pop","front":"How does Neoclassical theory differ from Classical population logic?","back":"Higher income can lower birth rates while lowering death rates, creating offsetting effects."},{"id":"neo-limit","front":"What major limitation of Neoclassical theory is emphasized?","back":"Technology arrives from outside the model; the theory does not explain what determines it."},{"id":"new-core","front":"What drives technological progress in New Growth Theory?","back":"Choices made in pursuit of self-interest and profit, not mere luck."},{"id":"new-human","front":"How does New Growth Theory explain human-capital growth?","back":"People choose education and training."},{"id":"new-discovery","front":"How does New Growth Theory explain discoveries?","back":"They depend on how many people search and how hard they try."},{"id":"profit-competition","front":"What role do profit and competition play in New Growth Theory?","back":"Discovery creates profit; competition erodes it and motivates further innovation/cost reduction."},{"id":"replication","front":"Why does replicable physical capital matter in New Growth Theory?","back":"Productive methods/capital can spread rather than remain unique to one producer."},{"id":"knowledge","front":"What special property of knowledge supports New Growth Theory?","back":"Many people can use it at once; spillovers/non-rival use weaken simple diminishing returns."},{"id":"agents-link","front":"How does New Growth Theory link back to Lecture 1 agents?","back":"Households build human capital; firms innovate/adopt technology to pursue profit."},{"id":"competition-nuance","front":"Does 'competition destroys profit' mean competition is generally bad?","back":"No. Eroded profit can create the incentive for continued innovation."}]},{"id":"ec214-l3-policy-v1","label":"Part 4 • Preconditions, Policy & Growth Formulas","description":"Institutions and policies that support sustained productivity growth.","cards":[{"id":"freedom","front":"What does economic freedom mean in the growth lecture?","back":"Ability to make personal/economic choices with fewer barriers from corruption or excessive restrictions."},{"id":"property","front":"Why do property rights support growth?","back":"Protection of physical, financial, and intellectual property strengthens incentives to work, save, and invest."},{"id":"markets","front":"Why are markets a growth precondition?","back":"They exchange information, products, and services and enable trade, saving, and investment."},{"id":"capital-hour","front":"What must happen to capital per hour of labor for sustained growth?","back":"Its growth rate must increase."},{"id":"human-growth","front":"What must happen to human capital for sustained growth?","back":"It must keep growing through education, training, and skills."},{"id":"tech-pace","front":"What must happen to technological change for sustained growth?","back":"Its pace must continue to advance."},{"id":"incentives","front":"What broad policy direction does the professor list?","back":"Create incentives to save, invest, and innovate."},{"id":"saving-policy","front":"Why encourage saving?","back":"Saving supplies funds for investment and capital accumulation."},{"id":"rd","front":"Why encourage research and development?","back":"R&D supports discoveries and technological progress."},{"id":"trade","front":"How can international trade support growth?","back":"It expands exchange, specialization, technology access, and market opportunities."},{"id":"education","front":"Why improve education quality?","back":"It raises human capital and labor productivity."},{"id":"slow-steady","front":"How does the professor characterize sustainable growth?","back":"Slow and steady growth can create very large cumulative gains over time."}]}]};const root=window.D_STUDY_FLASHCARD_BANKS=window.D_STUDY_FLASHCARD_BANKS||{};const b=root.ec214||(root.ec214={title:"EC214 Complete Lecture Flashcards",bankVersion:"ec214-v13.14",lectures:[]});b.lectures=Array.isArray(b.lectures)?b.lectures:[];b.lectures=b.lectures.filter(function(x){return x&&x.id!==lecture.id});b.lectures.push(lecture);})();